  /// The visitor's contact proved its company with a company-signed user_hash and still belongs to it; false when the company came only as a hint
  final bool companyVerified;

  /// `contact`.
  final WidgetVisitorContact? contact;

  /// The JSON object the API expects; unset optional properties are left out.
  Map<String, Object?> toJson() => {
    'id': id,
    'token': token,
    'expires_at': expiresAt.toUtc().toIso8601String(),
    'verified': verified,
    'company_verified': companyVerified,
    'contact': switch (contact) { null => null, final v => v.toJson() },
  };
}

/// `WidgetVisitorContact` of the ClickFix visitor API.
class WidgetVisitorContact {
  /// Creates a `WidgetVisitorContact`.
  const WidgetVisitorContact({
    required this.name,
    this.email,
    this.phone,
  });

  /// Decodes a `WidgetVisitorContact`; [at] is the JSON path used in errors.
  factory WidgetVisitorContact.fromJson(Map<String, Object?> json, [String at = 'WidgetVisitorContact']) => WidgetVisitorContact(
    name: _string(json['name'], '$at.name'),
    email: _optional(json['email'], '$at.email', (e, p) => _string(e, p)),
    phone: _optional(json['phone'], '$at.phone', (e, p) => _string(e, p)),
  );

  /// `name`.
  final String name;

  /// `email`.
  final String? email;

  /// `phone`.
  final String? phone;

  /// The JSON object the API expects; unset optional properties are left out.
  Map<String, Object?> toJson() => {
    'name': name,
    'email': email,
    'phone': phone,
  };
}

/// Values of `CustomFieldType` (the API may add more; fields keep the raw string).
abstract final class CustomFieldType {
  /// `text`.
  static const String text = 'text';

  /// `textarea`.
  static const String textarea = 'textarea';

  /// `number`.
  static const String number = 'number';

  /// `money`.
  static const String money = 'money';

  /// `date`.
  static const String date = 'date';

  /// `boolean`.
  static const String boolean = 'boolean';

  /// `select`.
  static const String select = 'select';

  /// `multiselect`.
  static const String multiselect = 'multiselect';

  /// `url`.
  static const String url = 'url';

  /// `email`.
  static const String email = 'email';

  /// `phone`.
  static const String phone = 'phone';

  /// `user`.
  static const String user = 'user';

  /// Every value this client knows.
  static const List<String> values = [text, textarea, number, money, date, boolean, select, multiselect, url, email, phone, user];
}

T? _optional<T extends Object>(Object? v, String at, T Function(Object e, String p) decode) =>
    v == null ? null : decode(v, at);

Never _invalid(String at, String expected, Object? v) =>
    throw FormatException('ClickFix visitor API: $at must be $expected, got ${v == null ? 'null' : v.runtimeType}');

Object _value(Object? v, String at) => v ?? _invalid(at, 'a value', v);

String _string(Object? v, String at) => v is String ? v : _invalid(at, 'a string', v);

int _int(Object? v, String at) => switch (v) {
  int() => v,
  double() when v == v.truncateToDouble() && v.isFinite => v.toInt(),
  _ => _invalid(at, 'an integer', v),
};

bool _bool(Object? v, String at) => v is bool ? v : _invalid(at, 'a boolean', v);

DateTime _dateTime(Object? v, String at) =>
    DateTime.tryParse(_string(v, at)) ?? _invalid(at, 'an RFC 3339 date-time', v);

Map<String, Object?> _json(Object? v, String at) => v is Map<String, Object?> ? v : _invalid(at, 'an object', v);

// A Go nil slice is encoded as null: read it as an empty array.
List<T> _list<T>(Object? v, String at, T Function(Object? e, String p) decode) {
  if (v == null) return <T>[];
  if (v is! List<Object?>) _invalid(at, 'an array', v);
  return [for (var i = 0; i < v.length; i++) decode(v[i], '$at[$i]')];
}

Map<String, T> _mapOf<T>(Object? v, String at, T Function(Object? e, String p) decode) => {
  for (final e in _json(v, at).entries) e.key: decode(e.value, '$at.${e.key}'),
};

/// The JSON object [v] (the `data` of a response), or a [FormatException]
/// naming [at]. Used by `WidgetApi` before a model's `fromJson`.
Map<String, Object?> widgetJsonObject(Object? v, String at) => _json(v, at);
